<?php
require_once 'connexion.php';
$sql = 'SELECT * FROM vehicule WHERE nombre_place >= 5';
try { $resultats = $pdo->query($sql)->fetchAll(); } catch (PDOException $e) { $resultats = []; $erreur = $e->getMessage(); }
?><!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Requête n°4</title><link rel="stylesheet" href="CSS/style.css"></head><body><header class="site-header"><h1>Requête n°4</h1><nav><?php for ($i=1;$i<=10;$i++): ?><a class="<?= $i===4?'active':'' ?>" href="requete<?= $i ?>.php">Requête <?= $i ?></a><?php endfor; ?></nav></header><main class="container"><p class="description">Afficher les véhicules qui ont au moins 5 places.</p><?php if(isset($erreur)): ?><p class="error">Erreur : <?= htmlspecialchars($erreur) ?></p><?php elseif(!$resultats): ?><p class="empty">Aucun véhicule trouvé.</p><?php else: ?><div class="table-wrapper"><table><thead><tr><?php foreach(array_keys($resultats[0]) as $colonne): ?><th><?= htmlspecialchars($colonne) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($resultats as $ligne): ?><tr><?php foreach($ligne as $valeur): ?><td><?= htmlspecialchars($valeur) ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></main></body></html>
